const reconstructCommentJournal = `-- name: ReconstructCommentJournal :many
WITH RECURSIVE journal AS (
 SELECT r.id, r.uuid, r.workspace_id, r.comment_id, r.parent_revision, r.source_revision, r.version, r.schema_version, r.kind, r.checkpoint, r.patches, r.channel, r.deleted, r.actor_uuid, r.event_id, r.occurred_at FROM comment_revisions r WHERE r.workspace_id=$1 AND r.comment_id=$2 AND r.uuid=$3
 UNION ALL SELECT p.id, p.uuid, p.workspace_id, p.comment_id, p.parent_revision, p.source_revision, p.version, p.schema_version, p.kind, p.checkpoint, p.patches, p.channel, p.deleted, p.actor_uuid, p.event_id, p.occurred_at FROM comment_revisions p JOIN journal c ON p.workspace_id=c.workspace_id AND p.comment_id=c.comment_id AND p.uuid=c.parent_revision WHERE c.checkpoint IS NULL
) SELECT id, uuid, workspace_id, comment_id, parent_revision, source_revision, version, schema_version, kind, checkpoint, patches, channel, deleted, actor_uuid, event_id, occurred_at FROM journal ORDER BY version
`

type ReconstructCommentJournalParams struct {
	WorkspaceID  int64     `json:"workspace_id"`
	CommentID    int64     `json:"comment_id"`
	RevisionUuid uuid.UUID `json:"revision_uuid"`
}

type ReconstructCommentJournalRow struct {
	ID             int64              `json:"id"`
	Uuid           uuid.UUID          `json:"uuid"`
	WorkspaceID    int64              `json:"workspace_id"`
	CommentID      int64              `json:"comment_id"`
	ParentRevision pgtype.UUID        `json:"parent_revision"`
	SourceRevision pgtype.UUID        `json:"source_revision"`
	Version        int64              `json:"version"`
	SchemaVersion  int32              `json:"schema_version"`
	Kind           string             `json:"kind"`
	Checkpoint     []byte             `json:"checkpoint"`
	Patches        []byte             `json:"patches"`
	Channel        string             `json:"channel"`
	Deleted        bool               `json:"deleted"`
	ActorUuid      uuid.UUID          `json:"actor_uuid"`
	EventID        int64              `json:"event_id"`
	OccurredAt     pgtype.Timestamptz `json:"occurred_at"`
}

func (q *Queries) ReconstructCommentJournal(ctx context.Context, arg ReconstructCommentJournalParams) ([]ReconstructCommentJournalRow, error) {
	rows, err := q.db.Query(ctx, reconstructCommentJournal, arg.WorkspaceID, arg.CommentID, arg.RevisionUuid)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReconstructCommentJournalRow{}
	for rows.Next() {
		var i ReconstructCommentJournalRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.WorkspaceID,
			&i.CommentID,
			&i.ParentRevision,
			&i.SourceRevision,
			&i.Version,
			&i.SchemaVersion,
			&i.Kind,
			&i.Checkpoint,
			&i.Patches,
			&i.Channel,
			&i.Deleted,
			&i.ActorUuid,
			&i.EventID,
			&i.OccurredAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

